CREATE TYPE "Role" AS ENUM ('PATIENT', 'DOCTOR', 'ADMIN');
CREATE TYPE "ConsultationStatus" AS ENUM ('BOOKED', 'CONFIRMED', 'IN_PROGRESS', 'COMPLETED', 'CANCELLED', 'NO_SHOW');
CREATE TYPE "PaymentStatus" AS ENUM ('PENDING', 'PAID', 'FAILED', 'REFUNDED');
CREATE TABLE "User" ("id" UUID NOT NULL, "email" VARCHAR(255) NOT NULL, "passwordHash" TEXT NOT NULL, "role" "Role" NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT true, "mfaSecret" TEXT, "mfaEnabled" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PatientProfile" ("id" UUID NOT NULL, "userId" UUID NOT NULL, "fullName" VARCHAR(160) NOT NULL, "phone" VARCHAR(32), "dateOfBirth" TIMESTAMP(3), CONSTRAINT "PatientProfile_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DoctorProfile" ("id" UUID NOT NULL, "userId" UUID NOT NULL, "fullName" VARCHAR(160) NOT NULL, "specialty" VARCHAR(100) NOT NULL, "bio" VARCHAR(2000), "consultationFee" INTEGER NOT NULL DEFAULT 0, "isVerified" BOOLEAN NOT NULL DEFAULT false, CONSTRAINT "DoctorProfile_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AvailabilitySlot" ("id" UUID NOT NULL, "doctorId" UUID NOT NULL, "startsAt" TIMESTAMP(3) NOT NULL, "endsAt" TIMESTAMP(3) NOT NULL, "timezone" VARCHAR(64) NOT NULL DEFAULT 'UTC', "isActive" BOOLEAN NOT NULL DEFAULT true, "isBooked" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AvailabilitySlot_pkey" PRIMARY KEY ("id"), CONSTRAINT "AvailabilitySlot_time_check" CHECK ("endsAt" > "startsAt"));
CREATE TABLE "Consultation" ("id" UUID NOT NULL, "patientId" UUID NOT NULL, "doctorId" UUID NOT NULL, "slotId" UUID NOT NULL, "status" "ConsultationStatus" NOT NULL DEFAULT 'BOOKED', "reason" VARCHAR(1000), "idempotencyKey" VARCHAR(128) NOT NULL, "cancelledAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Consultation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Prescription" ("id" UUID NOT NULL, "consultationId" UUID NOT NULL, "content" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Prescription_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Payment" ("id" UUID NOT NULL, "consultationId" UUID NOT NULL, "amount" INTEGER NOT NULL, "currency" VARCHAR(3) NOT NULL DEFAULT 'INR', "status" "PaymentStatus" NOT NULL DEFAULT 'PENDING', "providerReference" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Payment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "RefreshToken" ("id" UUID NOT NULL, "userId" UUID NOT NULL, "tokenHash" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "revokedAt" TIMESTAMP(3), "replacedById" UUID, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "RefreshToken_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AuditLog" ("id" UUID NOT NULL, "actorId" UUID, "action" VARCHAR(100) NOT NULL, "entityType" VARCHAR(100) NOT NULL, "entityId" VARCHAR(100), "requestId" VARCHAR(100), "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AuditLog_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE INDEX "User_role_isActive_idx" ON "User"("role", "isActive");
CREATE UNIQUE INDEX "PatientProfile_userId_key" ON "PatientProfile"("userId");
CREATE UNIQUE INDEX "DoctorProfile_userId_key" ON "DoctorProfile"("userId");
CREATE INDEX "DoctorProfile_specialty_isVerified_idx" ON "DoctorProfile"("specialty", "isVerified");
CREATE UNIQUE INDEX "AvailabilitySlot_doctorId_startsAt_endsAt_key" ON "AvailabilitySlot"("doctorId", "startsAt", "endsAt");
CREATE INDEX "AvailabilitySlot_doctorId_isActive_isBooked_startsAt_idx" ON "AvailabilitySlot"("doctorId", "isActive", "isBooked", "startsAt");
CREATE UNIQUE INDEX "Consultation_idempotencyKey_key" ON "Consultation"("idempotencyKey");
CREATE INDEX "Consultation_patientId_createdAt_idx" ON "Consultation"("patientId", "createdAt");
CREATE INDEX "Consultation_doctorId_status_createdAt_idx" ON "Consultation"("doctorId", "status", "createdAt");
CREATE INDEX "Consultation_status_createdAt_idx" ON "Consultation"("status", "createdAt");
CREATE INDEX "Consultation_slotId_status_idx" ON "Consultation"("slotId", "status");
CREATE UNIQUE INDEX "Prescription_consultationId_key" ON "Prescription"("consultationId");
CREATE UNIQUE INDEX "Payment_consultationId_key" ON "Payment"("consultationId");
CREATE UNIQUE INDEX "Payment_providerReference_key" ON "Payment"("providerReference");
CREATE UNIQUE INDEX "RefreshToken_tokenHash_key" ON "RefreshToken"("tokenHash");
CREATE INDEX "RefreshToken_userId_expiresAt_idx" ON "RefreshToken"("userId", "expiresAt");
CREATE INDEX "AuditLog_entityType_entityId_createdAt_idx" ON "AuditLog"("entityType", "entityId", "createdAt");
CREATE INDEX "AuditLog_actorId_createdAt_idx" ON "AuditLog"("actorId", "createdAt");
ALTER TABLE "PatientProfile" ADD CONSTRAINT "PatientProfile_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "DoctorProfile" ADD CONSTRAINT "DoctorProfile_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AvailabilitySlot" ADD CONSTRAINT "AvailabilitySlot_doctorId_fkey" FOREIGN KEY ("doctorId") REFERENCES "DoctorProfile"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Consultation" ADD CONSTRAINT "Consultation_patientId_fkey" FOREIGN KEY ("patientId") REFERENCES "PatientProfile"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Consultation" ADD CONSTRAINT "Consultation_doctorId_fkey" FOREIGN KEY ("doctorId") REFERENCES "DoctorProfile"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Consultation" ADD CONSTRAINT "Consultation_slotId_fkey" FOREIGN KEY ("slotId") REFERENCES "AvailabilitySlot"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Prescription" ADD CONSTRAINT "Prescription_consultationId_fkey" FOREIGN KEY ("consultationId") REFERENCES "Consultation"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Payment" ADD CONSTRAINT "Payment_consultationId_fkey" FOREIGN KEY ("consultationId") REFERENCES "Consultation"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "RefreshToken" ADD CONSTRAINT "RefreshToken_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_actorId_fkey" FOREIGN KEY ("actorId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
